package cn.cloudcurtain.tv;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class PosterQueryCacheTest {
 @Before public void reset(){PosterQueryCache.clear(RuntimeEnvironment.getApplication());}
 @Test public void sameTitleEpisodesReuseMetadataButDifferentYearsDoNot()throws Exception{PosterQueryCache first=new PosterQueryCache(RuntimeEnvironment.getApplication());MovieTitle query=new MovieTitle("The Thing","1982",false);MovieMetadata data=MovieMetadata.read(new JSONObject().put("title","The Thing").put("release_date","1982"),false);first.remember(query,data);PosterQueryCache other=new PosterQueryCache(RuntimeEnvironment.getApplication());assertEquals("1982",other.find(query).year);assertNull(other.find(new MovieTitle("The Thing","2011",false)));assertNull(other.find(new MovieTitle("The Thing","1982",true)));}
 @Test public void shortMissDoesNotEraseAConfirmedPosterAndLogoutClearsSharedResults()throws Exception{PosterQueryCache cache=new PosterQueryCache(RuntimeEnvironment.getApplication());MovieTitle query=new MovieTitle("The Thing","1982",false);cache.remember(query,null);assertTrue(cache.recentMiss(query));MovieMetadata data=MovieMetadata.read(new JSONObject().put("title","The Thing").put("release_date","1982"),false);cache.remember(query,data);assertFalse(cache.recentMiss(query));assertNotNull(cache.find(query));PosterQueryCache.clear(RuntimeEnvironment.getApplication());assertNull(cache.find(query));assertFalse(cache.recentMiss(query));}
 @Test public void legacyPublicMetadataCanBeReusedButConflictingFilmsAreNotChosen()throws Exception{android.content.SharedPreferences legacy=RuntimeEnvironment.getApplication().getSharedPreferences("poster-seed-fixture",0);MovieMetadata first=MovieMetadata.read(new JSONObject().put("id",1).put("title","Film: One").put("release_date","1982").put("poster_path","/cover.jpg"),false);legacy.edit().clear().putString("match:first",first.json().toString()).commit();PosterQueryCache cache=new PosterQueryCache(RuntimeEnvironment.getApplication());cache.seed(legacy);assertEquals("Film: One",cache.find(new MovieTitle("Film","1982",false)).title);PosterQueryCache.clear(RuntimeEnvironment.getApplication());MovieMetadata other=MovieMetadata.read(new JSONObject().put("id",2).put("title","Film: Two").put("release_date","1982").put("poster_path","/other.jpg"),false);legacy.edit().putString("match:other",other.json().toString()).commit();cache.seed(legacy);assertNull(cache.find(new MovieTitle("Film","1982",false)));legacy.edit().clear().commit();}
}
